/* !
 * \file add.asc
 * \brief Add operator basic sample
 */

#include <cstdint>
#include <vector>
#include <algorithm>
#include <iterator>

#include <iostream>

#include "acl/acl.h"

#include "kernel_operator.h"

template <uint32_t blockLength>
__vector__ __global__ void add_custom(__gm__ float* x, __gm__ float* y, __gm__ float* z)
{
    AscendC::InitSocState();

    AscendC::GlobalTensor<float> xGm, yGm, zGm;
    xGm.SetGlobalBuffer(x + block_idx * blockLength, blockLength);
    yGm.SetGlobalBuffer(y + block_idx * blockLength, blockLength);
    zGm.SetGlobalBuffer(z + block_idx * blockLength, blockLength);

    AscendC::LocalMemAllocator<AscendC::Hardware::UB> ubAllocator;
    AscendC::LocalTensor<float> xLocal = ubAllocator.Alloc<float, blockLength>();
    AscendC::LocalTensor<float> yLocal = ubAllocator.Alloc<float, blockLength>();
    AscendC::LocalTensor<float> zLocal = ubAllocator.Alloc<float, blockLength>();

    AscendC::DataCopy(xLocal, xGm, blockLength);
    AscendC::DataCopy(yLocal, yGm, blockLength);
    AscendC::PipeBarrier<PIPE_ALL>();

    AscendC::Add(zLocal, xLocal, yLocal, blockLength);
    AscendC::PipeBarrier<PIPE_ALL>();

#if 0
    // Debug I/O. Set #if 1 to enable print.
    AscendC::printf("%s\n", "[ DumpTensor in xLocal]");
    AscendC::DumpTensor(xLocal, 1, 32);

    AscendC::printf("%s\n", "[ DumpTensor in yLocal]");
    AscendC::DumpTensor(yLocal, 2, 32);

    AscendC::printf("%s\n", "[ DumpTensor in zLocal]");
    AscendC::DumpTensor(zLocal, 3, 32);
#endif

    AscendC::DataCopy(zGm, zLocal, blockLength);
    AscendC::PipeBarrier<PIPE_ALL>();
}

std::vector<float> kernel_add(std::vector<float>& x, std::vector<float>& y)
{
    constexpr uint32_t numBlocks = 8;
    constexpr uint32_t blockLength = 2048;
    uint32_t totalLength = x.size();
    size_t totalByteSize = totalLength * sizeof(float);
    float* xDevice = nullptr;
    float* yDevice = nullptr;
    float* zDevice = nullptr;
    uint8_t* zHost = nullptr;

    aclInit(nullptr);
    int32_t deviceId = 0;
    aclrtSetDevice(deviceId);
    aclrtStream stream = nullptr;
    aclrtCreateStream(&stream);

    aclrtMalloc((void**)&xDevice, totalByteSize, ACL_MEM_MALLOC_HUGE_FIRST);
    aclrtMalloc((void**)&yDevice, totalByteSize, ACL_MEM_MALLOC_HUGE_FIRST);
    aclrtMalloc((void**)&zDevice, totalByteSize, ACL_MEM_MALLOC_HUGE_FIRST);
    aclrtMallocHost((void**)&zHost, totalByteSize);

    aclrtMemcpy(xDevice, totalByteSize, x.data(), totalByteSize, ACL_MEMCPY_HOST_TO_DEVICE);
    aclrtMemcpy(yDevice, totalByteSize, y.data(), totalByteSize, ACL_MEMCPY_HOST_TO_DEVICE);

    add_custom<blockLength><<<numBlocks, 0, stream>>>(xDevice, yDevice, zDevice);
    aclrtSynchronizeStream(stream);

    aclrtMemcpy(zHost, totalByteSize, zDevice, totalByteSize, ACL_MEMCPY_DEVICE_TO_HOST);
    std::vector<float> z((float*)zHost, (float*)(zHost + totalByteSize));

    aclrtFree(xDevice);
    aclrtFree(yDevice);
    aclrtFree(zDevice);
    aclrtFreeHost(zHost);

    aclrtDestroyStream(stream);
    aclrtResetDevice(deviceId);
    aclFinalize();

    return z;
}

uint32_t VerifyResult(std::vector<float>& output, std::vector<float>& golden)
{
    auto printTensor = [](std::vector<float>& tensor, const char* name) {
        constexpr size_t maxPrintSize = 20;
        std::cout << name << ": ";
        std::copy(
            tensor.begin(), tensor.begin() + std::min(tensor.size(), maxPrintSize),
            std::ostream_iterator<float>(std::cout, " "));
        if (tensor.size() > maxPrintSize) {
            std::cout << "...";
        }
        std::cout << std::endl;
    };
    printTensor(output, "Output");
    printTensor(golden, "Golden");
    if (std::equal(golden.begin(), golden.end(), output.begin())) {
        std::cout << "test pass!" << std::endl;
        return 0;
    } else {
        std::cout << "test failed!" << std::endl;
        return 1;
    }
}

int32_t main(int32_t argc, char* argv[])
{
    constexpr uint32_t totalLength = 8 * 2048;
    std::vector<float> x(totalLength);
    std::vector<float> y(totalLength);

    for (uint32_t i = 0; i < totalLength; ++i) {
        x[i] = i * 0.1f;
        y[i] = i * 0.2f;
    }

    std::vector<float> output = kernel_add(x, y);

    std::vector<float> golden(totalLength);
    for (uint32_t i = 0; i < totalLength; ++i) {
        golden[i] = x[i] + y[i];
    }

    return VerifyResult(output, golden);
}

# 核函数<a name="ZH-CN_TOPIC_0000001564710756"></a>

核函数（Kernel Function）是在设备侧并行执行的C/C++函数。它由主机端代码调用，调用时被实例化为多份并行副本，分别调度到多个AI Core上运行（每个AI Core被抽象为一个Block）。这些Block利用AI Core的计算能力，协同完成某一算子的计算。


## 核函数的定义<a name="zh-cn_topic_0000001447989210_section1915102519220"></a>

定义核函数时需要遵循以下规则。

-   **使用函数类型限定符和函数执行空间限定符**

    除了需要按照C/C++函数声明的方式定义核函数之外，还要为核函数加上额外的函数类型限定符。

    必须使用\_\_global\_\_函数类型限定符来标识它是一个核函数，可以被<<<...\>\>\>调用。同时，需要根据算子实际执行的硬件单元，选择以下一种函数执行空间限定符，详情参考[函数执行空间限定符](../../语言扩展层/SIMD-BuiltIn关键字.md#section1074418132518)：
    -   \_\_aicore\_\_：标识该核函数在设备端AI核上执行，不区分具体核类型（通常用于[耦合模式](../../高级编程/硬件实现/基本架构.md#section1574769433)）。
    -   \_\_vector\_\_：标识该核函数在设备端Vector核上执行，适用于仅包含Vector计算的算子。
    -   \_\_cube\_\_：标识该核函数在设备端Cube核上执行，适用于仅包含Cube计算的算子。
    -   \_\_mix\_\_：标识该核函数同时在Cube核和Vector核上执行，适用于包含Vector和Cube融合计算的算子。

-   **使用变量类型限定符**

    指针入参变量需要增加变量类型限定符\_\_gm\_\_，表明该指针变量指向Global Memory上某处内存地址。

-   **其他规则**<a name="zh-cn_topic_0000001447989210_li94421027152419"></a>
    1.  规则：核函数必须具有void返回类型。
    2.  规则：核函数参数列表需遵循[函数参数列表限制](../../../技术附录/CPP标准支持/语法限制/函数.md#section_kernel_function_argument_list_constraint)。

-   代码示例如下：
    ```
    // Use the __global__ and __vector__ qualifiers to define kernel functions.
    __global__ __vector__ void add_kernel(__gm__ float* x, __gm__ float* y, __gm__ float* z)
    {
        ...
    }

    // Template-based definition of kernel functions is supported. An example of such a definition is provided below; it includes one type template parameter.
    template<typename T>
    __global__ __vector__ void add_kernel(__gm__ T* x, __gm__ T* y, __gm__ T* z)
    {
        ...
    }

    ```

## 核函数的调用

在Ascend C算子编程中，根据代码执行空间的不同，函数被严格划分为三类。它们之间的调用关系遵循如下规则：

-   Host侧执行函数：运行于主机端（CPU）。除了支持标准C/C++语义下的同类函数互调外，其核心作用是作为计算任务的发起者，通过内核调用符<<<...\>\>\>下发执行配置，跨界调用设备侧的核函数。
-   核函数（Kernel Function）：运行于设备端（NPU），是Host侧任务下发的执行入口。核函数在组织并行计算逻辑时，可以向下调用其他的Device侧执行函数。
-   Device侧执行函数：运行于设备端（NPU）的普通函数（除核函数外）。此类函数主要用于封装和复用底层计算逻辑，其调用权限被严格限制在设备侧内部，仅支持被核函数或同类的Device侧执行函数调用。

**图1**  核函数、host侧执行函数、device侧执行函数调用关系<a name="fig321723224511"></a>  
![](../../../figures/核函数-host侧执行函数-device侧执行函数调用关系.png "核函数-host侧执行函数-device侧执行函数调用关系")

Host侧通过内核调用符<<<...>>>的语法形式调用核函数，如下所示：

```
kernel_name<<<numBlocks, dynUBufSize, stream>>>(argument list);
```

`<<<...>>>`内的参数为核函数的执行配置，由3个参数决定，详细用法请参考[核函数配置](../../语言扩展层/SIMD-BuiltIn关键字.md#核函数配置)：

-   numBlocks：规定了核函数将会在几个核上执行，对于不同的硬件架构和算子类型，numBlocks的设置规则有一些区别，详见[核函数配置](../../语言扩展层/SIMD-BuiltIn关键字.md#核函数配置)。每个执行该核函数的核会被分配一个逻辑ID，即block\_idx，可以在核函数的实现中使用内置变量[block_idx](../../语言扩展层/SIMD-BuiltIn关键字.md#内置变量)获取。需要注意的是，在使用`__mix__`函数执行空间限定符的场景下，处在同一核上的Vector Core的block_idx取值相同，详细说明和示例请参考[内置变量](../../语言扩展层/SIMD-BuiltIn关键字.md#内置变量)；
-   dynUBufSize：Dynamic Unified Buffer Size，是配置UB动态内存分配的空间的大小（仅限UB，不包括L1 Buffer等），单位为bytes，默认设置为0；
-   stream：类型为aclrtStream，stream用于维护一些异步操作的执行顺序，确保按照应用程序中的代码调用顺序在device上执行，默认设置为nullptr。stream创建等管理接口请参考[《Runtime运行时API》](https://hiascend.com/document/redirect/CannCommunityRuntimeApi)。

如下名为add\_custom的核函数，实现两个矢量的相加，调用示例如下：

```
// numBlocks is set to 8: Indicates that the add_kernel function is invoked on 8 cores. Each core will execute the kernel independently and in parallel.
// dynUBufSize is set to 0: Indicates that no dynamic memory space is allocated for the Unified Buffer (UB). The argument list for the kernel is x, y, z.
add_kernel<<<8, 0, stream>>>(x, y, z);

// The invocation format for a template kernel function is as follows:
// 1. Process Float32 vector addition.
add_kernel<float><<<8, 0, stream>>>(x_float, y_float, z_float);
// 2. Simply change the template parameter to int32_t to perform integer computation.
add_kernel<int32_t><<<8, 0, stream>>>(x_int, y_int, z_int);
```

核函数的调用是异步的，核函数的调用结束后，控制权立刻返回给主机端，可以调用以下**aclrtSynchronizeStream**函数来强制主机端程序等待所有核函数执行完毕。

```
aclError aclrtSynchronizeStream(aclrtStream stream);
```

aclrtSynchronizeStream的具体用法参考[《Runtime运行时API》](https://hiascend.com/document/redirect/CannCommunityRuntimeApi)。

## Blocks索引内置变量

在通过 <<<numBlocks, ...>>> 启动多核并行计算后，多个AI Core会同时执行同一份核函数代码。为了避免多个核重复处理同一块数据，我们需要在代码中对全局数据进行切分。

Ascend C提供了内置变量block_idx和block_num，帮助每个核精准定位自己需要处理的数据切片：
-   block_num：获取当前核函数被分配的逻辑核总数（其值等于内核调用时配置的numBlocks）。
-   block_idx：获取当前执行代码的逻辑核ID，取值范围为[0, block_num - 1]。

在Mix场景（使用`__mix__`函数执行空间限定符）下，Vector核（AIV）还需要通过sub_block_idx来确定在组合内的位置：
-   sub_block_num：获取当前组合内Vector核的数量（即每个组合中AIV的个数）。
-   sub_block_idx：获取当前Vector核在组合内的索引，取值范围为[0, sub_block_num - 1]。

在Mix场景中，AIV核的完整逻辑位置由block_idx和sub_block_idx共同确定：`logic_idx = block_idx * sub_block_num + sub_block_idx`。开发者应使用[GetBlockIdx](../../../../api/SIMD-API/basic_api/tool_interface/system_resources_and_variables/GetBlockIdx.md)和[GetSubBlockIdx](../../../../api/SIMD-API/basic_api/tool_interface/system_resources_and_variables/GetSubBlockIdx_ISASI.md) API组合获取逻辑位置，而非直接使用内置变量（更多说明参见[内置变量](../../语言扩展层/SIMD-BuiltIn关键字.md#内置变量)中的注意事项）。

以下示例展示了如何利用block_idx和block_num，将总长度为TOTAL_LENGTH的一维数据均匀分配给多个核进行处理：

```
// Assume the total amount of data to be processed is predefined in a macro.
constexpr uint32_t TOTAL_LENGTH = 8192;

__global__ __vector__ void add_kernel(__gm__ float* x, __gm__ float* y, __gm__ float* z)
{
    // 1. Get the logical ID of the current core and the total number of logical cores participating in the computation.
    uint32_t core_idx = block_idx;
    uint32_t core_num = block_num;

    // 2. Calculate the amount of data to be processed by the current core.
    // Assume TOTAL_LENGTH is perfectly divisible by core_num.
    uint32_t data_per_core = TOTAL_LENGTH / core_num;

    // 3. Calculate the data offset of the current core in Global Memory.
    uint32_t offset = core_idx * data_per_core;

    // 4. Offset the global pointers to obtain the addresses of the data slices belonging to the current core.
    __gm__ float* x_local = x + offset;
    __gm__ float* y_local = y + offset;
    __gm__ float* z_local = z + offset;

    // 5. Subsequent logic: Each core independently processes its own data slice (e.g., move to UB, vector addition, write back, etc.).
    // op.Init(x_local, y_local, z_local, data_per_core);
    // op.Process();
}
```
假设我们通过add_kernel<<<8, 0, stream>>>(x, y, z);启动了上述核函数（即block_num = 8）。
-   当block_idx = 0的核执行时，它的offset = 0，将负责处理全局数组中索引从0到1023的数据。
-   当block_idx = 1的核执行时，它的offset = 1024，将负责处理全局数组中索引从1024到2047的数据。
-   以此类推，8个核完全并行且互不干扰地完成了8192个数据的计算。通过这种分片机制，block_idx实现了软硬件之间的一一映射。

# SIMD BuiltIn关键字<a name="ZH-CN_TOPIC_0000002509863893"></a>

## 预定义宏<a name="section2035104120360"></a>

如其他语言一样，会提供一些内置的宏方便用户编写程序。预定义宏一节着重介绍一些用户在做异构编程时会经常用到的宏，以及宏的解释。

-   <a id="npu-arch"></a>**\_\_NPU\_ARCH\_\_**

    \_\_NPU\_ARCH\_\_是Device侧AI Core代码中的预处理宏，用于标识AI处理器的架构版本。该宏由四位数字组成，其中前三位数字用于标识AI Core的IP核\(Intellectual Property Core\)类型，第四位数字标识该AI Core同一个IP核的配置版本。通过该宏，开发者可以针对不同AI处理器，差异化进行代码适配和优化。产品型号和NPU架构版本的对应关系如下：

    <!-- npu="950" id1 -->
    - Ascend 950PR/Ascend 950DT：3510
    <!-- end id1 -->
    <!-- npu="A3" id2 -->
    - Atlas A3 训练系列产品/Atlas A3 推理系列产品：2201
    <!-- end id2 -->
    <!-- npu="910b" id3 -->
    - Atlas A2 训练系列产品/Atlas A2 推理系列产品：2201
    <!-- end id3 -->
    <!-- npu="310b" id4 -->
    - Atlas 200I/500 A2 推理产品：3002
    <!-- end id4 -->
    <!-- npu="310p" id5 -->
    - Atlas 推理系列产品：2002
    <!-- end id5 -->
    <!-- npu="910" id6 -->
    - Atlas 训练系列产品：1001
    <!-- end id6 -->

    以下为通过\_\_NPU\_ARCH\_\_控制在不同AI处理器上算子输出值舍入模式的示例。

    ```
    __aicore__ static inline void CopyOut(uint64_t mulLen)
    {
    #if __NPU_ARCH__ == 2002
        Cast(dstLocal, srcLocal, RoundMode::CAST_NONE, mulLen); // CAST_NONE表示舍入模式在转换有精度损失时使用CAST_RINT模式，在不涉及精度损失时不进行舍入
    #elif __NPU_ARCH__ == 2201
        Cast(dstLocal, srcLocal, RoundMode::CAST_RINT, mulLen); // CAST_RINT表示舍入模式为四舍六入五成双舍入
    #endif
        event_t eventVToMTE3 = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::V_MTE3));
        SetFlag<HardEvent::V_MTE3>(eventVToMTE3);
        WaitFlag<HardEvent::V_MTE3>(eventVToMTE3);
        CommonCopyOut<float>(dstLocal, mulLen);  // 拷贝LocalTensor至GlobalTensor
    }
    ```

-   <a name="li19530175294118"></a>**ASCEND\_IS\_AIV、ASCEND\_IS\_AIC**

    ASCEND\_IS\_AIV和ASCEND\_IS\_AIC是通过C++宏实现的条件判断语句，用于在\_\_aicore\_\_修饰的函数中实现代码的条件编译。基于分离模式（AIC核和AIV核分离）开发融合算子时，算子逻辑中同时涉及AIV核和AIC核的处理逻辑，并需要进行核间同步，此时需要通过ASCEND\_IS\_AIV/ ASCEND\_IS\_AIC进行AIV和AIC核代码的隔离。

    >[!NOTE]说明
    >当使用高阶API Matmul时，其内部已通过REGIST\_MATMUL\_OBJ宏方式实现了AIV与AIC核代码的隔离，用户无需再使用该宏进行处理。

    以MatmulNzCustom算子为例，该算子在分离模式下需要分别在AIV核和AIC核上实现不同的逻辑。具体而言，AIV核负责将矩阵数据搬入Unified Buffer，完成数据的重排（将矩阵数据转换为NZ格式），并将其写入Global Memory。而AIC核则直接从Global Memory读取已经重排好的NZ格式数据，并执行矩阵乘法（Matmul）计算。由于AIV核和AIC核的代码逻辑不同，需要通过ASCEND\_IS\_AIV和ASCEND\_IS\_AIC宏进行代码隔离，确保在编译时分别生成适用于AIV核和AIC核的代码。

    示例伪码如下：

    ```
    template <typename AType, typename BType, typename CType, typename BiasType>
    __aicore__ inline void MatmulKernel<AType, BType, CType, BiasType>::Process(AscendC::TPipe *pipe)
    {
        // 利用AIV核的Vector计算单元实现ND2NZ格式转换。如下代码中MatrixBtoNZ为将B矩阵进行ND2NZ格式转换的函数。
        if ASCEND_IS_AIV {
            pipe->InitBuffer(ubBuf, TOTAL_UB_SIZE);
            MatrixBtoNZ<typename B_TYPE::T>(tempGM,
                bGMNZ,
                tiling,
                isTransB,
                ubBuf,
                tiling.baseK,
                tiling.baseN);  // Vector侧实现的ND2NZ函数
            SyncAll();
            // AIC核和AIV核同步
            AscendC::CrossCoreSetFlag<0x2, PIPE_MTE3>(0x4);
            return;
        }
        if ASCEND_IS_AIC {
            AscendC::CrossCoreWaitFlag(0x4);   // 等待AIV核完成ND2NZ格式转换
        }
        ... ...
        // 设置左矩阵A、右矩阵B、Bias。
        matmulObj.SetTail(tailM, tailN);
        matmulObj.SetTensorA(aGlobal, false);
        matmulObj.SetTensorB(bGlobal, false);
        if (tiling.isBias) {
            matmulObj.SetBias(biasGlobal);
        }
        // 完成矩阵乘操作
        matmulObj.IterateAll(cGlobal);
        // 结束矩阵乘操作
        matmulObj.End();
    }
    ```

-   **ASCENDC\_CUBE\_ONLY**

    ASCENDC\_CUBE\_ONLY是通过C++宏实现的条件判断语句，用于在\_\_aicore\_\_修饰的函数中实现代码的条件编译。

    基于分离模式开发非融合算子时，在只有矩阵计算的算子场景下，可以通过设置ASCENDC\_CUBE\_ONLY，开启纯Cube模式完成Matmul计算，减少消息通信的性能开销，提升算子性能。

    >[!CAUTION]注意
    >ASCENDC\_CUBE\_ONLY宏必须在\#include "lib/matmul\_intf.h"之前设置。

    以matmul\_custom算子为例，高阶API Matmul默认使用MIX模式，即用户从AIV侧发起消息，通过消息通信框架中转消息后，在AIC侧执行Matmul计算。这套消息处理机制会带来额外的Scalar性能开销。相较于MIX模式，纯Cube模式可以直接跳过消息通信框架，完成Matmul计算，提升算子性能。

    示例伪码如下：

    ```
    #define ASCENDC_CUBE_ONLY
    #include "lib/matmul_intf.h"

    using A_TYPE = AscendC::MatmulType<AscendC::TPosition::GM, CubeFormat::ND, AType>;
    using B_TYPE = AscendC::MatmulType<AscendC::TPosition::GM, CubeFormat::ND, BType>;
    using C_TYPE = AscendC::MatmulType<AscendC::TPosition::GM, CubeFormat::ND, CType>;
    using BIAS_TYPE =  AscendC::MatmulType<AscendC::TPosition::GM, CubeFormat::ND, BiasType>;
    AscendC::Matmul<A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_NORM> matmulObj;
    ```

## 函数执行空间限定符<a name="section1074418132518"></a>

函数执行空间限定符（Function Execution Space Qualifier）指示函数是在Host侧执行还是在Device侧执行，以及它是否可从Host侧或Device侧调用。

-   **\_\_global\_\_**

    \_\_global\_\_执行空间限定符声明一个Kernel函数。Kernel函数有如下性质：在Device上执行；只能被Host侧函数调用；\_\_global\_\_只是表示这是Device侧函数的入口，并不表示具体的设备类型，具体的设备类型由\_\_aicore\_\_标记。具有如下使用约束：

    -   一个\_\_global\_\_函数必须返回void类型，并且不能是class的成员函数。
    -   主机侧调用\_\_global\_\_函数必须使用<<<\>\>\>异构调用语法。
    -   \_\_global\_\_的调用是异步的，意味着函数返回，并不表示kernel函数在device侧已经执行完成，如果需要同步，需要使用Runtime同步接口显式同步，如**aclrtSynchronizeStream**接口。

-   **\_\_aicore\_\_**

    \_\_aicore\_\_执行空间限定符声明一个函数，它具有如下属性：

    -   在Device侧执行
    -   只能被\_\_global\_\_函数，或者其他\_\_aicore\_\_函数调用

    ```
    // Only callable from device functions with same kind
    // of execution space
    __aicore__ void bar() {}

    // Define a kernel function execute on AI Core device
    __global__ __aicore__ void foo() {
      bar(); // OK.
    }
    ```

-   **\_\_host\_\_**

    \_\_host\_\_执行空间限定符声明一个函数，它具有如下属性：

    -   只能在Host侧执行
    -   只能被Host侧函数调用
    -   \_\_global\_\_ 和\_\_host\_\_不能一起使用

    \_\_host\_\_限定符是可选项，无函数执行空间限定符定义的函数，默认是host函数。

    ```
    __aicore__ int f() {}

    // defines a host side function
    int foo() {}

    // defines a host side function
    __host__ int bar() {
      f();     // Error.
      foo();   // OK.
    }

    // Error.
    __global__ __host__ void kfunc() {}
    ```

-   **\_\_aicpu\_\_**

    AI CPU函数执行空间限定符\_\_aicpu\_\_用于指示函数是否为AI CPU Kernel函数，它具有如下属性：

    -   在Device侧执行且只能被Host侧函数调用，因此必须与\_\_global\_\_同时声明。
    -   一个\_\_global\_\_ \_\_aicpu\_\_函数不能是void返回类型，并且入参只能是一个指针。
    -   一个\_\_global\_\_ \_\_aicpu\_\_函数不能在.asc文件中进行定义，只能声明，且需要使用extern。
    -   Host侧调用\_\_global\_\_ \_\_aicpu\_\_函数时必须使用<<<\>\>\>异构调用语法，输入的函数入参在入参指针的基础上需要输入从指针中读取的数据大小。
    -   \_\_global\_\_的调用是异步的，意味着函数返回，并不表示kernel函数在Device侧已经执行完成，如果需要同步，需要使用Runtime同步接口显式同步，如**aclrtSynchronizeStream**接口

    ```
    // Define a AI CPU kernel function in AI CPU device file
    __aicpu__ void foo() {} // Error, single __aicpu__ identifier without _global__
    __global__ void foo() {} // Error, single __global__ identifier without __aicpu__
    __global__ __aicpu__  void foo() {} // Error, return type is void
    __global__ __aicpu__  int foo(void *a) {} // OK
    __global__ __aicpu__  int foo(int a) {} // Error, input param is not pointer
    __global__ __aicpu__  int foo(void *a, void *b) {} // Error, input param num is not one
    ```

    ```
    // Declare a AI CPU kernel function in .asc file
    extern __global__ __aicpu__ uint32_t hello_world(void *args);// OK
    ```

-   **\_\_inline\_\_**

    \_\_inline\_\_限定符声明一个函数，它具有如下属性：

    -   标识Device侧函数强制内联，可以减少函数频繁调用产生的指令压栈、出栈的开销，但可能会导致算子二进制增加。
    -   和C++函数修饰符inline的主要区别是Device侧\_\_inline\_\_是强制内联，C++的inline则是根据编译器优化选择性内联。
    -   AI Core对函数嵌套深度有限制，一般推荐嵌套深度不超过4层。使用强制内联可以减少调用层次。

-   **\_\_cube\_\_**

    标识该核函数仅在Cube核执行。针对耦合模式的硬件架构，该修饰符不生效。

    ```
    extern "C" __global__ __cube__ void mmad_custom(GM_ADDR a, GM_ADDR b, GM_ADDR c)
    {
        KernelMmad op;
        op.Init(a, b, c);
        op.Process();
    }
    ```

-   **\_\_vector\_\_**

    标识该核函数仅在Vector核执行。针对耦合模式的硬件架构，该修饰符不生效。

    ```
     __vector__ __global__ __aicore__ void add_custom(){}
    ```

-   **\_\_mix\_\_\(cube, vec\)**

    标识该核函数同时在Cube核和Vector核上执行。\(cube, vec\)分别表示核函数启动的Cube核和Vector核的配比，支持的配比为\(1, 0\)、\(0, 1\)、\(1, 1\)和\(1, 2\)。在该修饰符生效的非耦合架构上，`__mix__(1, 0)`等价于`__cube__`，`__mix__(0, 1)`等价于`__vector__`，可分别使用__cube__和__vector__替代。针对耦合模式的硬件架构，该修饰符不生效。

-   **\_\_schedmode\_\_\(mode\)**

    标识该核函数的执行调度模式。如下图所示：

    -   mode = 0 : normal mode，尽可能选择空闲物理核下发执行核函数，若空闲物理核数无法满足当前核函数的需要，没有下发的部分等待核心空闲后执行。此时OP1和OP2算子会存在交叠执行（overlap）的情况。

    -   mode = 1 : batch mode，在下发核函数时先进行判断，若空闲物理核数无法满足当前核函数的需要，则等待至空闲物理核数满足该核函数所需要的所有物理核时，同时下发执行，OP1和OP2的执行被切分（split）开，不会出现交叠执行的情况。

    ![](../../figures/batchmode资料.png)

    在多流并发场景，多算子并行执行时，若执行总核数超过最大物理核数，且多个算子逻辑使用SyncALL等核间同步接口时，建议设置mode为1，防止多个算子之间互相等待空闲核调度，导致死锁。默认值mode为0。

    ```
     __schedmode__(1) __global__ __mix__(1, 2) void OP1() // OP1使用了SyncAll接口，且存在多流并发的可能，需要设置batch mode（mode 1）
    {
        AscendC::SyncAll();
        ....
    }
     __schedmode__(1) __global__ __mix__(1, 2) void OP2() // OP2使用了SyncAll接口，且存在多流并发的可能，需要设置batch mode（mode 1）
    {
        AscendC::SyncAll();
        ....
    }
    __schedmode__(0) __global__ __vector__ void OP3() {...} // OP3没有使用SyncAll接口，可以设置为normal mode(mode 0)，按照正常规则执行算子。
    or
    __global__ __vector__ void OP3() {...} // 不设置__schedmode__，默认为normal mode。
    ```

## 函数标记宏<a name="section192521344610"></a>

-   \_\_simd\_vf\_\_

    函数标记宏，用于标记SIMD VF入口函数，函数无返回值。使用[asc\_vf\_call](../../../api/SIMD-API/basic_api/reg_vector_compute/vf_call/asc_vf_call.md)调用SIMD VF入口函数，启动VF子任务。

    ```
    __simd_vf__ inline void KernelAdd(__ubuf__ float* x, __ubuf__ float* y, __ubuf__ float* z)
    ```

    \_\_simd\_vf\_\_标记的SIMD VF有以下入参约束：

    -   支持指针传参（Pass-by-Pointer），指针变量必须用\_\_ubuf\_\_地址空间限定符修饰。
    -   不支持引用传参（Pass-by-Reference）。
    -   不支持函数指针传参。

        \_\_simd\_vf\_\_使用的示例如下：

        ```
        __simd_vf__ inline void simd_adds(__ubuf__ float *output, __ubuf__ float *input,
            uint32_t count, uint16_t oneRepeatSize, uint16_t repeatTimes)
        {
            AscendC::Reg::RegTensor<float> srcReg;
            AscendC::Reg::RegTensor<float> dstReg;
            // asc_update_mask() will be supported later.
            // init MaskReg with the count of all numbers.
            AscendC::Reg::MaskReg maskReg = AscendC::Reg::UpdateMask<float>(count);
            for (uint16_t i = 0; i < repeatTimes; i++) {
                // asc_load, asc_adds and asc_store will be supported later.
                // load data from UB to RegTensor.
                AscendC::Reg::LoadAlign(srcReg, input + i * oneRepeatSize);
                AscendC::Reg::Adds(dstReg, srcReg, 1.0f, maskReg);
                // store data from RegTensor to UB.
                AscendC::Reg::StoreAlign(output + i * oneRepeatSize, dstReg, maskReg);
            }
        }
        ```

-   \_\_simd\_callee\_\_

    函数标记宏，函数可以有返回值，允许被SIMD VF入口函数或其他非入口函数调用。

    ```
    __simd_callee__ inline float add(float x, float y)
    ```

## 地址空间限定符<a name="section1624210295308"></a>

AI Core具备多级独立片上存储，各个地址空间独立编址，具备各自的访存指令，根据架构差异，有些存储空间具备统一地址空间（Generic Address Space），有些则没有。设备侧编程基于语法扩展允许地址空间作为合法的类型限定符，以提供针对不同地址空间的访问能力和地址空间合法性检查。

**表2**  地址空间映射关系

| 地址空间限定符 | AI Core物理存储空间 |
|----------------|---------------------|
| __gm__ | 设备侧内存GM |
| __ubuf__ | Vector Unified Buffer |
| __ca__ | Cube L0A Buffer |
| __cb__ | Cube L0B Buffer |
| __cc__ | Cube L0C Buffer |
| __cbuf__ | Cube L1 Buffer |
| __fbuf__ | Fixpipe Buffer |
| __ssbuf__ | SSBuffer |

地址空间限定符可以在变量声明中使用，用于指定对象分配的区域。如果对象的类型被地址空间名称限定，那么该对象将被分配在指定的地址空间中。同样地，对于指针，指向的类型可以通过地址空间进行限定，以指示所指向的对象所在的地址空间。

```
// declares a pointer p in the __gm__ address space that
// points to an object(has int type) in the __gm__ address space
__gm__ int *p;

__global__ __aicore__ void foo(...)
{
  // declares an array of 4 floats in the private address space.
  float x[4];
}
```

地址空间限定符不能用于非指针返回类型，非指针函数参数，函数类型，同一个类型上不允许使用多个地址空间限定符。

```
// OK.
__aicore__ int f() {...}

// Error. Address space qualifier cannot be used with a non-pointer return type.
__ubuf__ int f() { ... }

// OK. Address space qualifier can be used with a pointer return type.
__ubuf__ int *f() { ... }

// Error. Multiple address spaces specified for a type.
__ubuf__ __gm__ int i;

// OK. The first address space qualifies the object pointed to and the second
// qualifies the pointer.
__ubuf__ int * __gm__ ptr;
```

>[!NOTE]说明
>**重要**：不同地址空间指针的大小可能不同。例如，不能认为sizeof\(\_\_gm\_\_ int \*\)总是等于sizeof\(\_\_ubuf\_\_ int \*\)，譬如编译器或许可能在某些系统上以32bit存储\_\_ubuf\_\_指针。

-   **private地址空间**

    private地址空间是大多数变量的默认地址空间，特别是局部变量。

    ```
    // m is in a specific kernel parameter address space,
    // it's physical location is implementation determined.
    __global__ __vector__ void foo(int m) {
      // OK. i is an int variable allocated in private address space
      int i;
    }

    __aicore__ void bar(int k) { //OK. k is in private address space
      // OK. i is an int variable allocated in private address space
      int i;
    }
    ```

-   **\_\_gm\_\_地址空间**

    \_\_gm\_\_地址空间限定符用来表示分配于设备侧全局内存的对象，全局内存对象可以声明为标量、用户自定义结构体的指针。

    ```
    __gm__ int *var; // var point to an array of int elements

    typedef struct {
        float a[3];
        int b[2];
    } foo_t;

    __gm__ foo_t *info; // info point to an array of foo_t elements
    ```

-   **\_\_ubuf\_\_地址空间**

    \_\_ubuf\_\_地址空间用来描述存储于AI Core核内UB存储空间的变量。

    ```
    __global__ __aicore__ void foo() {
      // ptr is in private address space, point to __ubuf__
      __ubuf__ int *ptr;
    }
    ```

-   **\_\_ca\_\_, \_\_cb\_\_, \_\_cc\_\_, \_\_cbuf\_\_地址空间**

    上述几个地址空间主要用于特定的DMA指令访问，不具备标量直接访问能力。

    ```
    class ObjTy{
      ObjTy(){...}
      void print(){...}

    private:
      int a;
      int b;
    };

    __global__ __aicore__
    void foo(__ca__ int * ptr) { // Error. Cannot have __ca__
                                 // qualifier in kernel arguments
      // OK
      __ca__ int *ptr;
    }
    ```

## 内置常量<a name="section784531219338"></a>

| 常量名 | 取值 | 功能 |
